// s04 r20: render the same motion shots for several query variants in ONE vite + browser (scratch tool, read-only).
//   node variants.mjs <outDir> <shots csv> <name=query> [<name=query> ...]
// shots: f03,f06,f10,f20,sl,sr,slh,srh,t33,t66,t95 (names as in tools/lead_r6/motion_audit.mjs)
import { mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, SHOTCSV, ...VARS] = process.argv.slice(2);
const ALL = { a00: ['a00_approved_view', 0, null], f03: ['f03_forward3u', 3, null], f06: ['f06_forward6u', 6, null],
  f10: ['f10_forward10u', 10, null], f20: ['f20_forward20u', 20, null], sl: ['s_left_steer', 6, -1], sr: ['s_right_steer', 6, 1],
  slh: ['s_left_hard', 12, -1], srh: ['s_right_hard', 12, 1], t33: ['t33_through_screen', 't0.33', null],
  t66: ['t66_through_screen', 't0.66', null], t95: ['t95_through_screen', 't0.95', null] };
const SHOTS = SHOTCSV.split(',').map((k) => ALL[k]);
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.PORT || 5273));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  for (const v of VARS) {
    const i = v.indexOf('='); const name = v.slice(0, i), Q = v.slice(i + 1);
    const dir = `${OUT}/${name}`; mkdirSync(dir, { recursive: true });
    const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
    page.on('pageerror', (e) => console.error('pageerror', e.message));
    page.on('console', (m) => { if (m.type() === 'error' && !/woff|font/i.test(m.text())) console.error('console', m.text()); });
    await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
    for (const [sn, dist, steer] of SHOTS) {
      const st = await page.evaluate(async ([id, dist, steer]) => {
        const r = window.__rainbow; r.goto(id);
        const s0 = r.state().s; const stg = r.course.stage(id); const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
        const target = typeof dist === 'string' ? s0 + Number(dist.slice(1)) * Math.max(0, s1 - s0) : s0 + dist;
        r.setSteer(steer); let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
        r.setSteer(null);
        r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
        return { ...r.state(), frames: n };
      }, ['04', dist, steer]);
      await page.waitForTimeout(150);
      await page.screenshot({ path: `${dir}/${sn}.png` });
      console.log(name, sn, 's', st.s?.toFixed?.(3), 'lat', st.lat, 'coins', st.coins);
    }
    await page.close();
  }
} finally { await browser.close(); await vite.close(); }

